.service-map {
  --surface: #1a1a19;
  --surface-raised: #222221;
  --hairline: #333331;
  --text-primary: #ffffff;
  --text-secondary: #c3c2b7;
  --text-muted: #8c8b83;
  --accent: #3987e5;
  color: var(--text-primary);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 4px 2px 12px;
}
.service-map.light {
  --surface: #fcfcfb;
  --surface-raised: #f4f3f0;
  --hairline: #dcdad4;
  --text-primary: #0b0b0b;
  --text-secondary: #52514e;
  --text-muted: #77766f;
  --accent: #256abf;
}
.service-map .stats {
  display: grid;
  grid-template-columns: minmax(220px, 2fr) repeat(4, minmax(130px, 1fr));
  gap: 12px;
}
.service-map .stat {
  box-shadow: 0 1px 0 #ffffff0d inset, 0 8px 24px #00000026;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 14px 16px;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: 12px;
}
.service-map .caption {
  color: var(--text-muted);
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.service-map .figure {
  font-size: 26px;
  font-weight: 600;
  line-height: 1.1;
}
.service-map .selection-name {
  font-size: 20px;
  font-weight: 600;
  line-height: 1.2;
}
.service-map .selection-url {
  color: var(--text-secondary);
  font-size: 13px;
}
.service-map .canvas {
  position: relative;
  background-color: var(--surface);
  background-image: radial-gradient(var(--hairline) 1px, transparent 1px);
  background-size: 22px 22px;
  border: 1px solid var(--hairline);
  border-radius: 14px;
  overflow: hidden;
}
.service-map svg {
  display: block;
  width: 100%;
  height: auto;
  max-height: 64vh;
}
.service-map .legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding: 12px 18px;
  color: var(--text-muted);
  font-size: 12px;
  border-top: 1px solid var(--hairline);
}
.service-map .legend .bar {
  width: 120px;
  height: 6px;
  border-radius: 3px;
}
.service-map .legend .hint {
  margin-left: auto;
}
.service-map .empty {
  padding: 80px 20px;
  text-align: center;
  color: var(--text-muted);
}
.service-map .node .card {
  fill: var(--surface-raised);
  stroke: var(--hairline);
  stroke-width: 1.5;
  filter: drop-shadow(0 6px 14px #00000040);
  transition: stroke 0.15s;
}
.service-map .node:hover .card,
.service-map .node:focus .card,
.service-map .node.pinned .card {
  stroke: var(--accent);
  stroke-width: 2;
}
.service-map .node.selected .card {
  stroke: var(--accent);
  stroke-width: 2;
  fill: color-mix(in srgb, var(--accent) 10%, var(--surface-raised));
}
.service-map .node .role-dot {
  fill: var(--text-muted);
}
.service-map .node.selected .role-dot {
  fill: var(--accent);
}
.service-map .node .traffic {
  fill: var(--text-muted);
  font-size: 11px;
  text-anchor: middle;
  font-variant-numeric: tabular-nums;
}
.service-map .node {
  outline: none;
  cursor: pointer;
  transition: opacity 0.2s;
}
.service-map .node.off {
  opacity: 0.35;
}
.service-map .node text {
  text-anchor: middle;
  pointer-events: none;
  fill: var(--text-primary);
}
.service-map .node .name {
  font-size: 15px;
  font-weight: 600;
}
.service-map .node .role {
  fill: var(--text-muted);
  font-size: 10px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-anchor: start;
}
.service-map .edge-group,
.service-map .edge-label,
.service-map .node {
  transition: opacity 0.2s;
}
.service-map .edge {
  opacity: 0.92;
}
.service-map .edge-hit {
  cursor: help;
}
.service-map .hidden {
  display: none;
}
.service-map .edge-label rect {
  fill: var(--surface);
  stroke: var(--hairline);
  stroke-width: 1;
}
.service-map .edge-label text {
  fill: var(--text-secondary);
  font-size: 12px;
  text-anchor: middle;
  pointer-events: none;
}
.service-map .edge-label .count {
  fill: var(--text-primary);
  font-weight: 700;
}
.service-map .dim {
  opacity: 0.14;
}
.service-map .stat .sub {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.35;
}
.service-map .chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.service-map .chip {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--hairline);
  border-radius: 999px;
  padding: 6px 14px;
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.service-map .chip:hover {
  border-color: var(--accent);
}
.service-map .chip.active {
  background: color-mix(in srgb, var(--accent) 18%, transparent);
  border-color: var(--accent);
  color: var(--text-primary);
}
.service-map .chip:focus-visible,
.service-map .node:focus-visible .card {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.service-map .tooltip {
  position: absolute;
  display: none;
  min-width: 220px;
  padding: 12px 14px;
  background: var(--surface-raised);
  border: 1px solid var(--hairline);
  border-radius: 12px;
  box-shadow: 0 12px 32px #00000066;
  font-size: 12.5px;
  color: var(--text-secondary);
  pointer-events: none;
  z-index: 5;
}
.service-map .tooltip strong {
  display: block;
  color: var(--text-primary);
  font-size: 13.5px;
}
.service-map .tooltip .tooltip-url {
  display: block;
  margin: 2px 0 8px;
  color: var(--accent);
}
.service-map .tooltip dl {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 16px;
  margin: 0;
}
.service-map .tooltip dd {
  margin: 0;
  color: var(--text-primary);
  font-weight: 600;
  text-align: right;
  font-variant-numeric: tabular-nums;
}
@media (prefers-reduced-motion: reduce) {
  .service-map * {
    transition: none !important;
  }
}
.service-map .table-view {
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: 12px;
  padding: 10px 16px;
  color: var(--text-secondary);
  font-size: 13px;
}
.service-map .table-view summary {
  cursor: pointer;
  color: var(--text-muted);
}
.service-map .table-view table {
  width: 100%;
  margin-top: 10px;
  border-collapse: collapse;
}
.service-map .table-view th,
.service-map .table-view td {
  padding: 6px 10px;
  text-align: left;
  border-bottom: 1px solid var(--hairline);
}
.service-map .table-view th {
  color: var(--text-muted);
  font-weight: 500;
}
.service-map .table-view .number {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.service-map .edge-group.hovered .edge {
  opacity: 1;
  filter: drop-shadow(0 0 6px var(--accent));
}
.service-map .edge-group.chosen .edge,
.service-map .edge-group.hovered .edge,
.service-map .edge-group.chain .edge {
  opacity: 1;
  stroke-dasharray: 10 8;
  animation: service-map-chain 0.9s linear infinite;
}
@keyframes service-map-chain {
  to { stroke-dashoffset: -18; }
}
@media (prefers-reduced-motion: reduce) {
  .service-map .edge-group.chosen .edge,
  .service-map .edge-group.hovered .edge,
  .service-map .edge-group.chain .edge {
    animation: none;
  }
}

.service-map .selection-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  border: 1px solid var(--accent);
  border-radius: 12px;
  color: var(--text-secondary);
  font-size: 13px;
}
.service-map .selection-bar[hidden] {
  display: none;
}
.service-map .selection-bar strong {
  color: var(--text-primary);
}
.service-map .selection-bar .bar-label {
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.service-map .selection-bar .bar-url {
  color: var(--accent);
}
.service-map .selection-bar .bar-clear {
  margin-left: auto;
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--hairline);
  border-radius: 8px;
  padding: 4px 12px;
  font: inherit;
  cursor: pointer;
}
.service-map .selection-bar .bar-clear:hover {
  border-color: var(--accent);
  color: var(--text-primary);
}
.service-map .node.chosen .card {
  stroke: var(--accent);
  stroke-width: 3;
  filter: drop-shadow(0 0 10px var(--accent));
}
.service-map .node.chosen .role {
  fill: var(--accent);
}
.service-map .edge-group.chosen .edge {
  opacity: 1;
  filter: drop-shadow(0 0 6px var(--accent));
}
.service-map .edge-label.chosen rect {
  stroke: var(--accent);
  stroke-width: 1.5;
}
.service-map .table-view .table-count {
  color: var(--text-muted);
  margin-left: 6px;
}
.service-map .table-view tr.hidden {
  display: none;
}
.service-map .table-view tr.related-row td {
  color: var(--text-primary);
}
.service-map .table-view tr.chosen-row td {
  color: var(--text-primary);
  font-weight: 700;
  background: color-mix(in srgb, var(--accent) 16%, transparent);
}
.service-map .table-view tr.chosen-row td:first-child {
  box-shadow: inset 3px 0 0 var(--accent);
}
